```python
import sys

def solve():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])

    rows = min(n, m)
    cols = max(n, m)
    full = (1 << rows) - 1

    def vert(x):
        return (x | (x << 1) | (x >> 1)) & full

    INF = float('inf')

    # Initialize DP for column 0
    dp = {}
    for x0 in range(full + 1):
        partial0 = vert(x0) | 0
        cost = bin(x0).count('1')
        state = (x0, partial0)
        if dp.get(state, INF) > cost:
            dp[state] = cost

    # Process remaining columns
    for col in range(1, cols):
        new_dp = {}
        for (prev_mask, partial), cost in dp.items():
            for x in range(full + 1):
                if (partial | x) != full:
                    continue
                new_partial = vert(x) | prev_mask
                new_state = (x, new_partial)
                new_cost = cost + bin(x).count('1')
                if new_dp.get(new_state, INF) > new_cost:
                    new_dp[new_state] = new_cost
        dp = new_dp

    best = INF
    for (prev_mask, partial), cost in dp.items():
        if partial == full:
            if cost < best:
                best = cost

    print(n * m - best)

